ours.prepare:
// The two examples the reference shows open (previews 4 and 5, "Sides" and "Skip transition"):
// every card pinned open, the pointer ignored so a stray hover cannot close one mid-read. The public
// docs page pins nothing; this is the census page only.
const previews = [...document.querySelectorAll(".showcase .preview")];
const els = previews.slice(3).flatMap((p) => [...p.querySelectorAll("acme-context-card")]);
for (const el of els) { el.disableTriggers = true; el.shown = 1; }
return Promise.all(els.map(async (el) => { await el.updateComplete; }));
